     1→import { NextRequest, NextResponse } from "next/server";
     2→
     3→export async function POST(req: NextRequest) {
     4→  const formData = await req.formData();
     5→  const file = formData.get("file");
     6→
     7→  if (!file || !(file instanceof File)) {
     8→    return NextResponse.json({ error: "No file provided" }, { status: 400 });
     9→  }
    10→
    11→  const allowed = /\.(gpx|fit)$/i;
    12→  if (!allowed.test(file.name)) {
    13→    return NextResponse.json(
    14→      { error: "Unsupported file type. Only .gpx and .fit files are accepted." },
    15→      { status: 400 }
    16→    );
    17→  }
    18→
    19→  // Log receipt of the file (no actual parsing)
    20→  console.log(`[upload] Received file: ${file.name} (${file.size} bytes, type: ${file.type})`);
    21→
    22→  // Return mock parsed data with random values
    23→  const distance = parseFloat((Math.random() * 60 + 10).toFixed(1)); // 10–70 km
    24→  const elevation = Math.round(Math.random() * 1200 + 50); // 50–1250 m
    25→  const durationMinutes = Math.round(distance * 2.5); // rough estimate
    26→  const hours = Math.floor(durationMinutes / 60);
    27→  const mins = durationMinutes % 60;
    28→  const secs = Math.round(Math.random() * 59);
    29→  const duration = `${hours}:${String(mins).padStart(2, "0")}:${String(secs).padStart(2, "0")}`;
    30→
    31→  const today = new Date().toISOString().split("T")[0];
    32→
    33→  return NextResponse.json({
    34→    id: crypto.randomUUID(),
    35→    date: today,
    36→    distance,
    37→    elevation,
    38→    duration,
    39→    message: "File received and parsed successfully (mock)",
    40→  });
    41→}
    42→

