                <stop
                  offset="0%"
                  style={{ stopColor: accentColor, stopOpacity: 0.8 }}
                />
                <stop
                  offset="100%"
                  style={{ stopColor: accentColor, stopOpacity: 0.1 }}
                />
              </linearGradient>
              {/* Gradient for area stroke */}
              <linearGradient id="elevationStrokeGradient" x1="0" y1="0" x2="0" y2="1">
                <stop
                  offset="0%"
                  style={{ stopColor: accentColor, stopOpacity: 1 }}
                />
                <stop
                  offset="100%"
                  style={{ stopColor: accentColor, stopOpacity: 0.3 }}
                />
              </linearGradient>
            </defs>

            {/* Grid lines */}
            <CartesianGrid
              strokeDasharray="3 3"
              stroke="#374151"
              vertical={false}
            />

            {/* X-axis */}
            <defs>
              <linearGradient id="axisGradient" x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stopColor="#9CA3AF" />
                <stop offset="100%" stopColor="#D1D5DB" />
              </linearGradient>
            </defs>

            <XAxis
              dataKey="distance"
              stroke="#6B7280"
              tick={{ fill: "#9CA3AF", fontSize: 12 }}
              tickFormatter={formatXAxis}
              height={30}
              tickLine={false}
              axisLine={{ stroke: "#374151" }}
            />

            {/* Y-axis */}
            <YAxis
              stroke="#6B7280"
              tick={{ fill: "#9CA3AF", fontSize: 12 }}
              tickFormatter={formatYAxis}
              width={50}
              tickLine={false}
              axisLine={{ stroke: "#374151" }}
            />

            {/* Tooltip */}
            <Tooltip
              content={<CustomTooltip />}
              cursor={{ stroke: accentColor, strokeWidth: 1, strokeDasharray: "4 4" }}
            />

            {/* Elevation area */}
            <Area
              type="monotone"
              dataKey="elevation"
              stroke="url(#elevationStrokeGradient)"
              strokeWidth={2}
              fill="url(#elevationGradient)"
              animationDuration={1500}
              activeDot={{
                r: 6,
                strokeWidth: 0,
                fill: accentColor,
                stroke: "#1F2937",
              }}
            />

            {/* Reference line at mean elevation */}
            <ReferenceLine
              y={stats.avg}
              stroke="#6B7280"
              strokeDasharray="3 3"
              label={{
                value: "Avg",
                position: "right",
                fill: "#6B7280",
                fontSize: 11,
              }}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>

      {/* Legend */}
      <div className="flex items-center justify-center gap-6 mt-4">
        <div className="flex items-center gap-2">
          <div
            className="w-3 h-3 rounded-full"
            style={{ backgroundColor: accentColor }}
          />
          <span className="text-xs text-gray-400">Elevation</span>
        </div>
        <div className="flex items-center gap-2">
